/*
 Problem: 2472. Maximum Number of Non-overlapping Palindrome Substrings
 Language: cpp
 Runtime: 252 ms (21.08%)
 Memory: 19.3 MB (46.07%)
 Tags: Two Pointers, String, Dynamic Programming, Greedy
*/
class Solution {
public:
    int maxPalindromes(string s, int k) {
        int n = s.size();
        vector<vector<bool>> pal(n, vector<bool>(n));

        for (int i = 0; i < n; ++i)
            pal[i][i] = true;

        for (int len = 2; len <= n; ++len) {
            for (int l = 0; l + len <= n; ++l) {
                int r = l + len - 1;
                pal[l][r] = s[l] == s[r] && (len <= 2 || pal[l + 1][r - 1]);
            }
        }

        vector<int> dp(n + 1);

        for (int i = 1; i <= n; ++i) {
            dp[i] = dp[i - 1];

            for (int j = 0; j < i; ++j) {
                if (i - j >= k && pal[j][i - 1])
                    dp[i] = max(dp[i], dp[j] + 1);
            }
        }

        return dp[n];
    }
};
